/**
 * 🔐 PENDING MESSAGE QUEUE
 * Sistema de fila de mensagens pendentes para decriptação posterior
 * Armazena mensagens criptografadas quando o sender key não está disponível
 * Processa automaticamente quando o sender key chegar
 */

import { getKeyBackupStore } from './key-backup-store.js'

export interface PendingMessage {
	id: string                    // Message ID
	groupJid: string              // Group JID
	participantJid: string        // Participant JID (author)
	senderKeyId: string           // Sender key identifier
	rawData: string               // Base64 encoded encrypted message data
	timestamp: number             // When message was received
	retryCount: number            // How many times we tried to process
}

// Callback para processar mensagem quando sender key chegar
type MessageProcessor = (pending: PendingMessage) => Promise<boolean>

// Registrar processadores para quando sender key chegar
const messageProcessors: Map<string, MessageProcessor> = new Map()

/**
 * Adiciona uma mensagem à fila de pendentes
 */
export async function addToPendingQueue(
	messageId: string,
	groupJid: string,
	participantJid: string,
	senderKeyId: string,
	encryptedData: Uint8Array
): Promise<boolean> {
	const store = getKeyBackupStore()
	
	try {
		const pending: PendingMessage = {
			id: messageId,
			groupJid,
			participantJid,
			senderKeyId,
			rawData: Buffer.from(encryptedData).toString('base64'),
			timestamp: Date.now(),
			retryCount: 0
		}
		
		return await store.addPendingMessage(pending)
	} catch (error) {
		console.warn('[PENDING-QUEUE] Failed to add message to queue:', error)
		return false
	}
}

/**
 * Processa mensagens pendentes para um sender key específico
 * Chamado quando um novo sender key é recebido
 */
export async function processPendingMessages(
	senderKeyId: string,
	processor: MessageProcessor
): Promise<number> {
	const store = getKeyBackupStore()
	let processed = 0
	
	try {
		const pending = await store.getPendingMessages(senderKeyId)
		
		for (const msg of pending) {
			try {
				const success = await processor(msg)
				if (success) {
					await store.removePendingMessage(msg.id)
					processed++
					console.log(`[PENDING-QUEUE] ✅ Processed pending message ${msg.id}`)
				} else {
					// Incrementar retry count
					msg.retryCount++
					if (msg.retryCount >= 3) {
						// Desistir após 3 tentativas
						await store.removePendingMessage(msg.id)
						console.warn(`[PENDING-QUEUE] ❌ Gave up on message ${msg.id} after 3 retries`)
					}
				}
			} catch (error) {
				console.warn(`[PENDING-QUEUE] Error processing message ${msg.id}:`, error)
			}
		}
	} catch (error) {
		console.warn('[PENDING-QUEUE] Error processing pending messages:', error)
	}
	
	return processed
}

/**
 * Registra um processador de mensagens para um sender key
 */
export function registerMessageProcessor(senderKeyId: string, processor: MessageProcessor): void {
	messageProcessors.set(senderKeyId, processor)
}

/**
 * Remove processador de mensagens
 */
export function unregisterMessageProcessor(senderKeyId: string): void {
	messageProcessors.delete(senderKeyId)
}

/**
 * Obtém processador registrado
 */
export function getMessageProcessor(senderKeyId: string): MessageProcessor | undefined {
	return messageProcessors.get(senderKeyId)
}

/**
 * Limpa mensagens antigas da fila (mais de 1 hora)
 */
export async function cleanupOldPendingMessages(): Promise<number> {
	const store = getKeyBackupStore()
	return await store.cleanupOldPendingMessages(60 * 60 * 1000) // 1 hora
}

/**
 * Obtém estatísticas da fila
 */
export async function getPendingQueueStats(): Promise<{ total: number; byGroup: Record<string, number> }> {
	const store = getKeyBackupStore()
	return await store.getPendingQueueStats()
}
